head.b:skin:
:root{--ink:#07111f;--panel:#0d1d34;--panel-2:#122746;--line:rgba(145,167,255,.22);--text:#f4f7ff;--muted:#a9b9d0;--cyan:#58d8ff;--violet:#91a7ff;--gold:#ffd37a;--red:#ff6673;--max:1180px}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:radial-gradient(circle at 85% -10%,#18365c 0,transparent 36%),var(--ink);color:var(--text);font-family:Arial,Helvetica,sans-serif;line-height:1.55}
a{color:var(--cyan);text-decoration:none}
a:hover{color:#fff}
.ticker{min-height:32px;padding:7px 12px;background:linear-gradient(90deg,#102d4f,#245b88,#102d4f);border-bottom:1px solid var(--line);color:#edf7ff;font-size:10px;font-weight:800;letter-spacing:.2em;text-align:center;text-transform:uppercase}
.site-shell{width:min(var(--max),calc(100% - 32px));margin:0 auto}
.site-header{position:relative;overflow:hidden;margin:24px 0 14px;padding:38px 34px;border:1px solid var(--line);border-radius:26px;background:linear-gradient(135deg,#102746,#172b55 56%,#17223d);box-shadow:0 20px 60px rgba(0,0,0,.26)}
.site-header:after{content:"";position:absolute;right:-100px;top:-130px;width:320px;height:320px;border:34px solid rgba(145,167,255,.12);border-radius:50%}
.site-nav{position:relative;z-index:2;display:flex;justify-content:flex-end;gap:18px;margin-bottom:30px;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.site-nav a{color:#c3d2ea}.site-nav a:hover{color:var(--cyan)}
.hall-of-fame{display:grid;grid-template-columns:180px minmax(0,1fr);align-items:center;gap:20px;margin:26px 0;padding:20px 24px;border:1px solid var(--line);border-radius:20px;background:linear-gradient(110deg,rgba(18,39,70,.96),rgba(12,28,50,.96))}.hall-of-fame h2{margin:0;color:#fff;font-size:24px}.legend-grid{display:grid;grid-template-columns:repeat(5,minmax(70px,1fr));gap:10px}.legend-card{display:flex;align-items:center;gap:8px;color:#dce7f8;font-size:11px;font-weight:800}.legend-card span{display:grid;place-items:center;width:42px;height:42px;border:2px solid var(--violet);border-radius:14px;background:linear-gradient(135deg,#1d4f78,#483f83);color:#fff;font-size:10px;box-shadow:0 6px 16px rgba(0,0,0,.2)}
.eyebrow{position:relative;z-index:1;margin:0 0 10px;color:var(--cyan);font-size:11px;font-weight:800;letter-spacing:.22em;text-transform:uppercase}
.site-title{position:relative;z-index:1;margin:0;color:#fff;font-size:clamp(30px,5vw,62px);line-height:1;letter-spacing:-.045em}
.site-description{position:relative;z-index:1;max-width:700px;margin:16px 0 0;color:#c0cee2;font-size:14px}
.live-date{display:flex;align-items:center;gap:8px;margin:14px 0 24px;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}
.live-date:before{content:"";width:8px;height:8px;border-radius:50%;background:var(--cyan);box-shadow:0 0 0 5px rgba(88,216,255,.12)}
.live-date strong{color:#fff;letter-spacing:0;text-transform:none}
.content-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:24px}
.post-card{overflow:hidden;border:1px solid var(--line);border-radius:22px;background:linear-gradient(180deg,rgba(18,39,70,.97),rgba(10,25,45,.97));box-shadow:0 18px 45px rgba(0,0,0,.2)}
.post-header{padding:26px 28px 12px}
.post-title{margin:0;color:#fff;font-size:clamp(24px,4vw,40px);line-height:1.12}
.post-title a{color:inherit}
.post-meta{margin-top:8px;color:var(--muted);font-size:11px}
.post-body{padding:10px 28px 30px;color:#d3ddef;font-size:15px}
.post-body img{max-width:100%;height:auto;border-radius:16px}
.post-body table{width:100%;border-collapse:separate;border-spacing:0;overflow:hidden;border:1px solid var(--line);border-radius:16px;background:#0b172a}
.post-body th{padding:12px 14px;background:#142d50;color:#aebfea;font-size:10px;letter-spacing:.08em;text-align:left;text-transform:uppercase}
.post-body td{padding:13px 14px;border-top:1px solid rgba(145,167,255,.13);color:#dbe5f7;font-size:12px}
.post-body tr:hover td{background:rgba(145,167,255,.07)}
.post-footer{padding:14px 28px;border-top:1px solid var(--line);color:var(--muted);font-size:11px}
.fixture-board-link{display:inline-flex;align-items:center;gap:8px;margin-top:14px;padding:10px 14px;border-radius:999px;background:linear-gradient(135deg,var(--cyan),#2b9fe6);color:#03111e;font-size:11px;font-weight:900;letter-spacing:.05em;text-transform:uppercase}
.fixture-board-link:hover{background:var(--violet);color:#06101f}
.site-footer{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:28px 0;padding:22px 0;border-top:1px solid var(--line);color:var(--muted);font-size:11px}
.site-footer a{color:#b9d4ff}
.hidden-seo{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
@media(max-width:700px){.site-shell{width:min(100% - 20px,var(--max))}.site-header{margin-top:14px;padding:28px 22px;border-radius:20px}.site-nav{justify-content:center;gap:12px;margin-bottom:24px;font-size:9px}.post-header{padding:22px 18px 10px}.post-body{padding:10px 18px 24px}.post-body table,.post-body thead,.post-body tbody,.post-body tr,.post-body td{display:block}.post-body thead{display:none}.post-body tr{padding:13px 0;border-top:1px solid var(--line)}.post-body tr:first-child{border-top:0}.post-body td{padding:3px 0;border:0}.hall-of-fame{display:block;padding:18px}.legend-grid{grid-template-columns:repeat(3,1fr);margin-top:16px}.legend-card{display:block;text-align:center}.legend-card span{margin:0 auto 5px}.site-footer{display:block}.site-footer span{display:block;margin-top:6px}}

body.script:
(function(){
  function updateCricketDate(){
    var target=document.getElementById('cricket-live-date-value');
    if(!target){return;}
    var parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Dhaka',weekday:'long',month:'long',day:'numeric',year:'numeric'}).formatToParts(new Date());
    var output='';
    parts.forEach(function(part){if(part.type!=='literal'){output+=part.value;}else{output+=part.value;}});
    target.textContent=output;
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',updateCricketDate);}else{updateCricketDate();}
  window.setInterval(updateCricketDate,60000);
})();
